import{_ as t,a,b as o,c as i,d as r}from"./chunks/qr_libre2direct_samsung_30.BlQvG7BZ.js";import{_ as s,o as n,c as h,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const w=JSON.parse('{"title":"Libre 2 Direct","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshoot/libre2direct.md","filePath":"troubleshoot/libre2direct.md"}'),u={name:"troubleshoot/libre2direct.md"};function c(d,e,p,m,b,g){return n(),h("div",null,[...e[0]||(e[0]=[l('<h1 id="libre2-direct" tabindex="-1">Libre2 Direct <a class="header-anchor" href="#libre2-direct" aria-label="Permalink to &quot;Libre2 Direct&quot;">​</a></h1><p>Libre2 (EU only) can connect directly to xDrip without a bridge. This page gives information on what a working system should look like.</p><p>See here to <a href="./../install/libre2.html#prerequisites">learn how to set it up...</a></p><h2 id="what-it-should-look-like" tabindex="-1">What it should look like <a class="header-anchor" href="#what-it-should-look-like" aria-label="Permalink to &quot;What it should look like&quot;">​</a></h2><p>When it has been set up correctly, and a new sensor is running, the xDrip status pages &amp; logs should appear as is shown below. Note - there is nothing different on the Uploaders tab for Libre 2 direct operation.</p><p>Go to xDrip System Status and also BT device. If you don&#39;t know how, look <a href="./systemstatus.html">here</a> first.</p><h2 id="classic-status-page" tabindex="-1">Classic Status Page <a class="header-anchor" href="#classic-status-page" aria-label="Permalink to &quot;Classic Status Page&quot;">​</a></h2><img src="'+t+'" style="zoom:40%;"><h3 id="version" tabindex="-1">Version <a class="header-anchor" href="#version" aria-label="Permalink to &quot;Version&quot;">​</a></h3><p>Will vary with your xDrip version</p><h3 id="data-source" tabindex="-1">Data Source <a class="header-anchor" href="#data-source" aria-label="Permalink to &quot;Data Source&quot;">​</a></h3><p>This should show as LimiTTer. Whilst misleading, this is normal behaviour.</p><h3 id="bluetooth-device" tabindex="-1">Bluetooth Device <a class="header-anchor" href="#bluetooth-device" aria-label="Permalink to &quot;Bluetooth Device&quot;">​</a></h3><p>This is the unique serial ID for the sensor. It will start with ABBOTT...</p><h3 id="connection-status" tabindex="-1">Connection status <a class="header-anchor" href="#connection-status" aria-label="Permalink to &quot;Connection status&quot;">​</a></h3><p>This should be &quot;connected&quot;.</p><h3 id="sensor-start" tabindex="-1">Sensor Start <a class="header-anchor" href="#sensor-start" aria-label="Permalink to &quot;Sensor Start&quot;">​</a></h3><p>The time the sensor is started.</p><h3 id="restart-collector-button" tabindex="-1">Restart Collector button <a class="header-anchor" href="#restart-collector-button" aria-label="Permalink to &quot;Restart Collector button&quot;">​</a></h3><p>This stops the collector function in xDrip and then starts it from scratch (includes Bluetooth connection to the device that was stopped)</p><h3 id="forget-device-button" tabindex="-1">Forget Device button <a class="header-anchor" href="#forget-device-button" aria-label="Permalink to &quot;Forget Device button&quot;">​</a></h3><p>This removes the Bluetooth device from known devices: you need to scan Bluetooth to find it and pair it, or NFC scan again.</p><h3 id="refresh-button" tabindex="-1">Refresh button <a class="header-anchor" href="#refresh-button" aria-label="Permalink to &quot;Refresh button&quot;">​</a></h3><p>The status is not real time, unlike the BT device tab; refresh checks connection state. <br></p><h2 id="bt-device-page" tabindex="-1">BT Device Page <a class="header-anchor" href="#bt-device-page" aria-label="Permalink to &quot;BT Device Page&quot;">​</a></h2><p>Swipe the screen towards the left to display the BT Device page.</p><img src="'+a+'" style="zoom:40%;"><h3 id="bluetooth-collector-status" tabindex="-1">Bluetooth Collector Status <a class="header-anchor" href="#bluetooth-collector-status" aria-label="Permalink to &quot;Bluetooth Collector Status&quot;">​</a></h3><h3 id="phone-service-state" tabindex="-1">Phone Service State <a class="header-anchor" href="#phone-service-state" aria-label="Permalink to &quot;Phone Service State&quot;">​</a></h3><p>This should normally give the time that the last connection was made. Sometimes it reads XXX Blu Con XXX, but this is a temporary phase, and will change to Last Connect HH:MM</p><h3 id="bluetooth-device-1" tabindex="-1">Bluetooth Device <a class="header-anchor" href="#bluetooth-device-1" aria-label="Permalink to &quot;Bluetooth Device&quot;">​</a></h3><p>Bluetooth should always be connected.</p><h3 id="device-mac-address" tabindex="-1">Device Mac Address <a class="header-anchor" href="#device-mac-address" aria-label="Permalink to &quot;Device Mac Address&quot;">​</a></h3><p>This should be a string of six pairs of Hex numbers. Unique for each sensor.</p><h3 id="bluetooth-pairing" tabindex="-1">Bluetooth Pairing <a class="header-anchor" href="#bluetooth-pairing" aria-label="Permalink to &quot;Bluetooth Pairing&quot;">​</a></h3><p>This should stay &quot;Disabled, tap to enable&quot;. Be careful to NOT tap this.<br> If you tap it by mistake, tap it again until it returns to disabled.</p><h3 id="slowest-wake-up" tabindex="-1">Slowest wake up <a class="header-anchor" href="#slowest-wake-up" aria-label="Permalink to &quot;Slowest wake up&quot;">​</a></h3><p>You can ignore this. xDrip doesn&#39;t spend its time waiting for readings: it will start expecting them after a certain time (traditionally 5 minutes). If no data arrives at that time, you&#39;ll see &quot;Woke up early&quot; meaning xDrip was expecting data to be ready but there&#39;s none. Slowest wake up is the highest delay encountered before receiving data normally.</p><h3 id="next-wake-up" tabindex="-1">Next Wake up <a class="header-anchor" href="#next-wake-up" aria-label="Permalink to &quot;Next Wake up&quot;">​</a></h3><p>Should say 5 minutes</p><br><h1 id="event-logs" tabindex="-1">Event Logs <a class="header-anchor" href="#event-logs" aria-label="Permalink to &quot;Event Logs&quot;">​</a></h1><p>From the vertical ... menu at the top right of the main screen, select View Events Log</p><img src="'+o+'" style="zoom:40%;"><h3 id="libreoopalgorithm" tabindex="-1">LibreOOPAlgorithm <a class="header-anchor" href="#libreoopalgorithm" aria-label="Permalink to &quot;LibreOOPAlgorithm&quot;">​</a></h3><p>You should see a row of comments of the format HH:MM Creating BG time = NNN raw = RRRR where HH:MM is the time, NNN is an internal time counter (a new reading has a number higher than the previous one), and RRRR is the raw value taken from the sensor, in tenths of mg/dl (1000 is 100 mg/dl or 5.5 mmol/l). This shows that the sensor is connected, and good readings are being taken. The reading should be every minute, although some might have been skipped, as has happened here.</p><br><h2 id="cannot-nfc-scan-new-sensor-nfc-timeout" tabindex="-1">Cannot NFC Scan new sensor - NFC Timeout <a class="header-anchor" href="#cannot-nfc-scan-new-sensor-nfc-timeout" aria-label="Permalink to &quot;Cannot NFC Scan new sensor - NFC Timeout&quot;">​</a></h2><p>There is an emerging problem, especially in Europe, where you cannot start the sensor with an NFC scan. Instead of the &quot;Scanned OK&quot; message after &quot;Scanning&quot;, you will see &quot;NFC read timeout&quot; or &quot;NFC diag timeout&quot;. Look in the debug logs. If you see a message &quot;Sensor type unknown, returning libre1 as failsafe&quot;, or &quot;Libre sensor of type Libre1 detected&quot;, then you need to update both OOP2 &amp; xDrip.</p><img src="'+i+'" style="zoom:40%;"><p>You will need to download a version of OOP2 from the end of May 2023, and also upgrade xDrip-plus so that it is 2023-05-27 or later. A newer version of the sensors, &quot;C5&quot; with updated firmware, requires these updated versions.</p><h2 id="losing-bluetooth-connection-with-samsung-phone" tabindex="-1">Losing Bluetooth Connection with Samsung Phone? <a class="header-anchor" href="#losing-bluetooth-connection-with-samsung-phone" aria-label="Permalink to &quot;Losing Bluetooth Connection with Samsung Phone?&quot;">​</a></h2><p>A number of people who have a Samsung phone have reported that they sometimes lose connection with the sensor. If this is the case with you, you can try changing some Bluetooth settings. Click on the QR code and then scan as directed.</p><p><a href="./libre2direct-qr-samsung.html"><img src="'+r+'" style="zoom:50%;"></a></p><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2023.05.26" target="_blank" rel="noreferrer"><em>Last modified 4/6/2023</em></a></p>',55)])])}const k=s(u,[["render",c]]);export{w as __pageData,k as default};
